// builds the WebAssembly synth voice: src/wasm/voice.c → src/engine/03w_voice_wasm.js (the module as base64, embedded in the
// engine bundle: no extra file to fetch, works inside an AudioWorklet and a Worker). Needs clang with the wasm32 target.
// The generated file is kept in src/, so a normal build does not need clang. Usage: node tools/wasm_build.cjs
const { execFileSync } = require('child_process'), fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..'), C = path.join(ROOT, 'src', 'wasm', 'voice.c'), OUT = path.join(ROOT, 'src', 'engine', '03w_voice_wasm.js'), TMP = path.join(ROOT, 'build', 'voice.wasm');
fs.mkdirSync(path.dirname(TMP), { recursive: true });
execFileSync('clang', ['--target=wasm32', '-O3', '-nostdlib', '-fno-builtin', '-mnontrapping-fptoint', '-mbulk-memory', '-ffp-contract=off', '-Wall', '-Wno-unused-function',
  '-Wl,--no-entry', '-Wl,-z,stack-size=65536', '-Wl,--strip-all', '-o', TMP, C], { stdio: 'inherit' });
const b = fs.readFileSync(TMP), src = fs.readFileSync(C, 'utf8'), h = require('crypto').createHash('sha256').update(src).digest('hex').slice(0, 16);
fs.writeFileSync(OUT, `/* generated by tools/wasm_build.cjs from src/wasm/voice.c (sha256 ${h}) — do not edit */\nconst VOICE_WASM_B64 = '${b.toString('base64')}';\nconst VOICE_WASM_SRC = '${h}';\n`);
console.log(`voice.wasm ${b.length} bytes → ${path.relative(ROOT, OUT)}`);
